import { expect, it } from "vite-plus/test";

import { formatIssueAutomationWriteBackComment } from "./issueAutomationWriteBack.ts";

it.each([
  {
    report: "## 问题根因分析\n内部代码和验证细节",
    reason: "本次报告未提供简明原因，请在 T3 Code 查看诊断详情。",
  },
  {
    report: "## 禅道评论\r\n\r\n问题原因：删除失败的原因仍在排查。\r\n本次使用 skill：example",
    reason: "删除失败的原因仍在排查。",
  },
])("does not publish report details when there is no solution summary", ({ report, reason }) => {
  expect(formatIssueAutomationWriteBackComment(report)).toBe(
    [
      `问题原因：${reason}`,
      "",
      "[T3-Auto-Analysis]",
      "Generated by ym-dev-zenbug AI Agent Skill",
    ].join("\n"),
  );
});
